<?php
require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/customer_utility_v1030.php';
if(!sk1030_table_exists('customer_saved_utilities_v1030')||!sk1030_table_exists('customer_utility_alerts_v1030'))exit("v10.3.0 reminder tables unavailable\n");
$today=(int)date('j');$month=date('Y-m');$made=0;
try{$q=db()->query('SELECT * FROM customer_saved_utilities_v1030 WHERE enabled=1 ORDER BY id');$rows=$q->fetchAll()?:[];$alert=db()->prepare('INSERT INTO customer_utility_alerts_v1030(tenant_id,user_id,alert_type,title,body,target_url,created_at) VALUES(?,?,?,?,?,?,NOW())');$mark=db()->prepare('UPDATE customer_saved_utilities_v1030 SET last_alert_month=?,updated_at=NOW() WHERE id=?');foreach($rows as $r){$due=max(1,min(31,(int)$r['due_day']));$before=max(0,min(15,(int)$r['reminder_days']));$days=$due-$today;if($days<0)$days+=31;if($days<=$before&&($r['last_alert_month']??'')!==$month){$title=(string)$r['provider'].' reminder';$body=(string)$r['label'].' is due around day '.$due.'.';$alert->execute([(int)$r['tenant_id'],(int)$r['user_id'],'utility_due',$title,$body,'/my-shahkot.php']);$mark->execute([$month,(int)$r['id']]);$made++;}}}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}echo "Created $made utility reminder alert(s).\n";
